  "ensemble": [
    { "figure": "<a figure/side, quoted from the plain visual read>", "entity": "<me | my bestie | my friends | my situationship (only under the cross-side exception) | ...>", "fit": <0-1>, "reason": "<one sentence grounded in what the figure visibly is>" }
  ],
  "weakest_fit": <the lowest fit in the ensemble>,
  "why": "<one sentence: how well this lens fits the image overall>",
  "secondary_nominations": [
    { "entity": "<a secondary entity, copied VERBATIM from the extracted entities — empty array if there are none>", "possibilities": ["<1-3 short phrases from her world in this lens>"] }
  ]
}

